219	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
220	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
221	        if (currentOwner == null) {
222	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	        }
224	        currentOwner.setAddress(ownerFieldsDto.getAddress());
225	        currentOwner.setCity(ownerFieldsDto.getCity());
226	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
227	        currentOwner.setLastName(ownerFieldsDto.getLastName());
228	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
229	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
230	        this.clinicService.saveOwner(currentOwner);
231	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
232	    }
