26	/**
27	 * Produces the stable identifier shared by the members of a household. The identifier is
28	 * derived deterministically from the household's {@link HouseholdKey}, so every owner in the
29	 * same household maps to the same value regardless of creation order.
30	 */
31	@Component
32	public class HouseholdIdGenerator {
33	
34	    private final HouseholdKey householdKey;
35	
36	    public HouseholdIdGenerator(HouseholdKey householdKey) {
37	        this.householdKey = householdKey;
38	    }
39	
40	    /** @return the stable household identifier for {@code owner}, e.g. {@code "HH-3F2A9C1E7B4D6058"}. */
41	    public String generate(Owner owner) {
42	        return "HH-" + shaHex(householdKey.of(owner), 16);
43	    }
44	
45	    /** First {@code n} upper-case hex characters of the SHA-256 digest of {@code value}. */
46	    private String shaHex(String value, int n) {
47	        byte[] digest = sha256(value.getBytes(StandardCharsets.UTF_8));
48	        StringBuilder hex = new StringBuilder(digest.length * 2);
49	        for (byte b : digest) {
50	            hex.append(String.format("%02X", b));
51	        }
52	        return hex.substring(0, n);
53	    }
54	
55	    private byte[] sha256(byte[] bytes) {
56	        try {
57	            return MessageDigest.getInstance("SHA-256").digest(bytes);
58	        }
59	        catch (NoSuchAlgorithmException ex) {
60	            throw new IllegalStateException("SHA-256 not available", ex);
61	        }
62	    }
63	}
